BEGIN;

-- Atomically select and lock the highest priority pending job
SELECT id, payload
FROM queue_jobs
WHERE status = 'PENDING'
ORDER BY priority DESC, created_at ASC
LIMIT 1
FOR UPDATE SKIP LOCKED;

-- Update status for the claimed job
UPDATE queue_jobs
SET status = 'PROCESSING', started_at = NOW()
WHERE id = $claimed_id;

COMMIT;

-- No explicit lock needed: the update is atomic
UPDATE counters
SET value = value + 1
WHERE name = 'page_views';

-- Lock multiple rows in ascending id order to avoid deadlocks
BEGIN;
SELECT id, balance
FROM accounts
WHERE id IN (42, 7)
ORDER BY id
FOR UPDATE;

UPDATE accounts SET balance = balance - 100 WHERE id = 7;
UPDATE accounts SET balance = balance + 100 WHERE id = 42;
COMMIT;
